#[test]
fn teardown_kills_a_tmux_server_that_a_late_child_starts() {
    let setup = Setup::new("teardown-late-tmux");
    // As a daemon's child in its own process group, still starting a session when the test ends.
    let mut late = setup
        .command("sh")
        .args(["-c", "sleep 0.5; tmux new-session -d sleep 100"])
        .process_group(0)
        .spawn()
        .unwrap();
    let dir = setup.tmux.path().to_owned();

    drop(setup);
    // Once the child is gone, so is any tmux client it ran: a server it started is running now.
    late.wait().unwrap();

    // With TMUX_TMPDIR gone, tmux falls back to the shared /tmp socket, so look for what it inherited.
    let Some(left) = tmux_dir::inheriting(&dir) else {
        eprintln!(
            "skipped the check: this host has no /proc to find a server that outlived the test"
        );
        return;
    };
    if !left.is_empty() {
        let _ = Command::new("kill").arg("-9").args(&left).output();
    }
    assert!(
        left.is_empty(),
        "processes {left:?} outlived the test, a tmux server among them"
    );
}

/// Whether process `pid` has exited. An init that reaps late, as in some containers, leaves a dead
/// process a zombie for a while. Without `/proc`, a zombie counts as alive.
fn exited(pid: &str) -> bool {
    if !Path::new("/proc/self/stat").exists() {
        let alive = Command::new("kill").args(["-0", pid]).output().unwrap();
        return !alive.status.success();
    }
    fs::read_to_string(format!("/proc/{pid}/stat")).map_or(true, |stat| {
        stat.rsplit_once(") ")
            .is_some_and(|(_, rest)| rest.starts_with(['Z', 'X']))
    })
}

#[test]
fn a_test_that_panics_after_its_run_starts_leaves_no_tmux_server() {
    let mut server = None;
    let caught = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut setup = Setup::new("teardown-after-panic");
        setup.publish(&requested(42));
        setup.start();
        setup.until("outbox", |rows| with(rows, 3, "confirmed") >= 1);
        let pid = setup.tmux(&["display-message", "-p", "#{pid}"]);
        let pid = String::from_utf8(pid.stdout).unwrap().trim().to_owned();
        server = Some((socket(&setup), pid));
        panic!("the test fails while its agent runs");
    }));

    assert!(caught.is_err());
    let (socket, pid) = server.expect("the run never got a tmux session");
    if Path::new("/proc/self/stat").exists() {
        assert!(exited(&pid), "tmux server {pid} outlived its test");
    } else {
        eprintln!("skipped the pid check: this host has no /proc to tell whether {pid} lives");
    }
    let listed = Command::new("tmux")
        .args(["-S", &socket, "list-sessions"])
        .output()
        .unwrap();
    assert!(!listed.status.success(), "a tmux server outlived its test");
    assert!(
        !Path::new(&socket).parent().unwrap().exists(),
        "the socket directory outlived its test"
    );
}

