/// Asserts the task stays asleep with `runs` runs for a while.
fn stays_asleep_after(setup: &Setup, runs: usize) {
    std::thread::sleep(Duration::from_millis(1500));
    assert_eq!(setup.rows("tasks")[0][4], "asleep");
    assert_eq!(setup.rows("runs").len(), runs);
}

#[test]
fn green_checks_at_the_result_commit_mark_the_task_done_and_start_no_run() {
    let setup = gated("gate-green");
    // A red check completed in the same poll, so its event comes next.
    let mut seen_red = check(4, 0);
    seen_red.data["failing"] = json!(1);

    setup.publish(&check(1, 1));
    setup.publish(&seen_red);
    stays_asleep_after(&setup, 2);
    setup.publish(&check(2, 0));

    setup.until("tasks", |rows| rows[0][4] == "done");
    std::thread::sleep(Duration::from_millis(1500));
    assert_eq!(setup.rows("runs").len(), 2);
    assert_eq!(setup.typed().len(), 2, "{:?}", setup.typed());
    assert!(setup.rows("waits").is_empty());
}

const AFTER_MERGE: &str = r#"
start = "implement"

[[steps]]
id = "implement"
decides = "model"
agent = "implementer"
prompt = "Implement the issue."
effect = "reversible"
next = { passed = "watch", failed = "stop" }

[[steps]]
id = "watch"
after = "merged"
decides = "model"
agent = "implementer"
prompt = "Watch the release."
effect = "read"
next = { quiet = "done" }
"#;

#[test]
fn green_checks_leave_a_task_before_a_step_after_the_merge_asleep_and_the_merge_enters_it() {
    let mut setup = Setup::with_workflow("after-merge", AFTER_MERGE);
    setup.calls(&[
        wait(on_pull_7("review")),
        passed_at("abc0000000000000000000000000000000000000"),
        json!({ "name": "result", "arguments": { "outcome": "quiet", "summary": "all quiet" } }),
    ]);
    setup.publish(&requested(42));
    setup.start();
    setup.until("runs", |rows| rows.len() == 1 && rows[0][7] == "asleep");
    setup.publish(&reviewed());
    setup.until("runs", |rows| rows.len() == 2 && rows[1][7] != "-");

    setup.publish(&check(1, 0));
    stays_asleep_after(&setup, 2);
    setup.publish(&closed());

    setup.until("tasks", |rows| rows[0][4] == "done");
    let runs = setup.rows("runs");
    assert_eq!(runs.len(), 3, "{runs:?}");
    assert_eq!(runs[2][2], "watch");
    assert!(
        setup
            .typed()
            .iter()
            .any(|text| text.contains("Watch the release.")),
        "{:?}",
        setup.typed()
    );
}

#[test]
fn a_merge_that_moves_a_said_run_to_another_agent_kills_its_session_and_starts_the_next_step() {
    let workflow = AFTER_MERGE.replace(
        "agent = \"implementer\"\nprompt = \"Watch",
        "agent = \"reviewer\"\nprompt = \"Watch",
    );
    let mut setup = Setup::with_workflow("after-merge-said", &workflow);
    setup.calls(&[
        wait(on_pull_7("review")),
        passed_at("abc0000000000000000000000000000000000000"),
        serde_json::Value::Null,
        json!({ "name": "result", "arguments": { "outcome": "quiet", "summary": "all quiet" } }),
    ]);
    setup.publish(&requested(42));
    setup.start();
    setup.until("runs", |rows| rows.len() == 1 && rows[0][7] == "asleep");
    setup.publish(&reviewed());
    setup.until("runs", |rows| rows.len() == 2 && rows[1][7] == "asleep");
    // The person's turn is still going when the pull request merges.
    setup.hold("hold-stop");
    assert!(setup.priory(&["say", "1", "Hold on."]).status.success());
    setup.until("outbox", |_| {
        setup
            .typed()
            .iter()
            .any(|text| text.starts_with("A person says: Hold on."))
    });
    let said = fs::read_to_string(setup.dir.join("fake/pid")).unwrap();

    setup.publish(&closed());
    setup.release("hold-stop");

    setup.until("tasks", |rows| rows[0][4] == "done");
    let runs = setup.rows("runs");
    assert_eq!(runs.len(), 4, "{runs:?}");
    assert_eq!(runs[3][2], "watch");
    // Killing its session hangs the agent up, and it exits once it is scheduled.
    let deadline = Instant::now() + Duration::from_secs(60);
    while !exited(said.trim()) {
        assert!(
            Instant::now() < deadline,
            "the said run's agent {said} still runs"
        );
        std::thread::sleep(Duration::from_millis(50));
    }
}

#[test]
fn a_merge_that_carries_a_said_run_into_the_next_step_queues_only_that_steps_ending() {
    let mut setup = Setup::with_workflow("after-merge-said-ending", AFTER_MERGE);
    setup.calls(&[
        wait(on_pull_7("review")),
        passed_at("abc0000000000000000000000000000000000000"),
        serde_json::Value::Null,
        json!({ "name": "result", "arguments": { "outcome": "quiet", "summary": "all quiet" } }),
    ]);
    setup.publish(&requested(42));
    setup.start();
    setup.until("runs", |rows| rows.len() == 1 && rows[0][7] == "asleep");
    setup.publish(&reviewed());
    setup.until("runs", |rows| rows.len() == 2 && rows[1][7] == "asleep");
    setup.hold("hold-stop");
    assert!(setup.priory(&["say", "1", "Hold on."]).status.success());
    setup.until("outbox", |_| {
        setup
            .typed()
            .iter()
            .any(|text| text.starts_with("A person says: Hold on."))
    });
    // The run is busy, so this one stays queued, with the ending of the step the task is at.
    assert!(setup.priory(&["say", "1", "And this."]).status.success());

    setup.publish(&closed());
    setup.until("runs", |rows| rows.len() == 4 && rows[3][2] == "watch");
    setup.release("hold-stop");

    setup.until("tasks", |rows| rows[0][4] == "done");
    let typed = setup.typed();
    let watch = typed
        .iter()
        .find(|text| text.contains("Watch the release."))
        .expect("the watch step's prompt was typed");
    assert!(watch.contains("A person says: And this."), "{watch}");
    assert!(watch.contains("outcomes: quiet."), "{watch}");
    assert!(!watch.contains("outcomes: failed, passed"), "{watch}");
}

#[test]
fn a_merge_after_a_said_runs_silent_turn_drops_its_nudge_from_the_next_steps_prompt() {
    let mut setup = Setup::with_workflow("after-merge-said-nudge", AFTER_MERGE);
    setup.calls(&[
        wait(on_pull_7("review")),
        passed_at("abc0000000000000000000000000000000000000"),
        serde_json::Value::Null,
        json!({ "name": "result", "arguments": { "outcome": "quiet", "summary": "all quiet" } }),
    ]);
    setup.publish(&requested(42));
    setup.start();
    setup.until("runs", |rows| rows.len() == 1 && rows[0][7] == "asleep");
    setup.publish(&reviewed());
    setup.until("runs", |rows| rows.len() == 2 && rows[1][7] == "asleep");
    setup.hold("hold-stop");
    assert!(setup.priory(&["say", "1", "Hold on."]).status.success());
    setup.until("outbox", |_| {
        setup
            .typed()
            .iter()
            .any(|text| text.starts_with("A person says: Hold on."))
    });
    // The merge waits on the log while the silent turn's Stop queues its nudge; the daemon reads
    // the log before it types again, so the nudge is still queued when the task enters `watch`.
    setup.publish(&closed());
    setup.release("hold-stop");

    setup.until("tasks", |rows| rows[0][4] == "done");
    let typed = setup.typed();
    let watch = typed
        .iter()
        .find(|text| text.contains("Watch the release."))
        .expect("the watch step's prompt was typed");
    assert!(
        !watch.contains("Your last turn ended in text only"),
        "{watch}"
    );
    assert!(!watch.contains("outcomes listed below"), "{watch}");
    assert!(watch.contains("outcomes: quiet."), "{watch}");
}

