fn thread_comment() -> Message {
    on_pull(
        "github.pull_request_review_comment",
        json!({
            "actor": "ana",
            "body": "Rename this.\nIt reads better.",
            "path": "src/lib.rs",
            "line": 12,
            "thread": 801,
            "url": "https://github.com/owner/repo/pull/7#discussion_r802",
            "github_id": 802
        }),
    )
}

