#[test]
fn a_gate_in_a_worktree_away_from_the_branch_head_runs_nothing_and_records_nothing() {
    let setup = Setup::proving("proof-detached", "touch ran", "passed");
    let worktree = setup.dir.join("home/worktrees/owner/repo/1");
    let head = setup.head();
    for args in [
        &[
            "-c",
            "user.name=t",
            "-c",
            "user.email=t@t",
            "commit",
            "-q",
            "--allow-empty",
            "-m",
            "more",
        ][..],
        &["checkout", "-q", "--detach", &head],
    ] {
        assert!(git(&worktree).args(args).status().unwrap().success());
    }

    let gate = setup.gate();

    assert_eq!(gate.status.code(), Some(1));
    assert_eq!(
        String::from_utf8_lossy(&gate.stderr),
        format!(
            "priory gate: the worktree is at {head}, not at the head of its branch, {}: check out the branch, then run it again\n",
            git(&worktree)
                .args(["rev-parse", "priory/1"])
                .output()
                .map(|out| String::from_utf8(out.stdout).unwrap().trim().to_owned())
                .unwrap()
        )
    );
    assert!(!worktree.join("ran").exists());
    let (text, error) = setup.proved();
    assert!(error && text.contains("no gate ran for task 1"), "{text}");
}

const TWO_MODEL_STEPS: &str = r#"
start = "implement"

[[steps]]
id = "implement"
decides = "model"
agent = "implementer"
prompt = "Implement the issue."
effect = "reversible"
next = { passed = "check", failed = "stop" }

[[steps]]
id = "check"
decides = "model"
agent = "reviewer"
prompt = "Check the change."
effect = "reversible"
next = { passed = "done", failed = "stop" }
"#;

/// Task 1 edits `shared.txt` and sits in its `check` run. Task 2 then edits `second` and ends its
/// `implement` run. Returns once task 2 left `implement`.
fn overlapping(name: &str, second: &str, factory: &str) -> Setup {
    overlapping_after(name, second, factory, |_| {})
}

fn overlapping_after(name: &str, second: &str, factory: &str, first: impl Fn(&Setup)) -> Setup {
    let mut setup = Setup::with_workflow(name, TWO_MODEL_STEPS);
    fs::write(setup.dir.join("factory/factory.toml"), factory).unwrap();
    setup.publish(&requested(42));
    setup.start();
    setup.until("tasks", |rows| with(rows, 4, "running") == 1);
    setup.commit(1, "shared.txt");
    setup.calls(&[passed_with_evidence()]);
    setup.until("runs", |rows| {
        rows.len() == 2 && rows[1][2] == "check" && rows[1][6] == "-"
    });
    // Task 1's silent turn gets its nudge, which would take the next queued call.
    setup.until("outbox", |rows| {
        rows.iter()
            .any(|row| row[2] == "2" && row[4].starts_with("Your last turn ended"))
    });
    first(&setup);
    setup.publish(&requested(43));
    setup.until("tasks", |rows| with(rows, 4, "running") == 2);
    setup.commit(2, second);
    setup.calls(&[passed_with_evidence()]);
    setup.until("tasks", |rows| {
        rows.iter()
            .any(|row| row[0] == "2" && row[3] != "implement")
    });
    setup
}

fn state_of(setup: &Setup, task: &str) -> (String, String) {
    let tasks = setup.rows("tasks");
    let row = tasks.iter().find(|row| row[0] == task).unwrap();
    (row[4].clone(), row[7].clone())
}

#[test]
fn a_task_whose_files_overlap_an_earlier_active_task_is_held_until_that_task_ends() {
    let setup = overlapping("overlap-held", "shared.txt", "name = \"demo\"");
    setup.until("tasks", |rows| {
        rows.iter().any(|row| row[0] == "2" && row[4] != "ready")
    });

    let (state, reason) = state_of(&setup, "2");

    assert_eq!(state, "held");
    assert!(
        reason.starts_with("held: overlaps task 1 on shared.txt, until task 1 ends"),
        "{reason}"
    );
}

#[test]
fn a_task_on_other_files_than_an_earlier_task_is_not_held() {
    let setup = overlapping("overlap-disjoint", "other.txt", "name = \"demo\"");

    setup.until("tasks", |rows| {
        rows.iter().any(|row| row[0] == "2" && row[4] == "running")
    });

    assert_eq!(state_of(&setup, "2").0, "running");
}

#[test]
fn a_factory_with_overlap_off_holds_no_task() {
    let setup = overlapping(
        "overlap-off",
        "shared.txt",
        "name = \"demo\"\n\n[queue]\noverlap = false\n",
    );

    setup.until("tasks", |rows| {
        rows.iter().any(|row| row[0] == "2" && row[4] == "running")
    });

    assert_eq!(state_of(&setup, "2").0, "running");
}

#[test]
fn a_task_overlapping_one_with_an_open_pull_request_is_held_until_it_merges() {
    let setup = overlapping_after("overlap-merge", "shared.txt", "name = \"demo\"", |setup| {
        let db = rusqlite::Connection::open(setup.dir.join("priory.db")).unwrap();
        db.execute(
            "INSERT INTO pull_requests (task, resource, branch, base)
             VALUES (1, 'github:owner/repo#7', 'priory/1', 'main')",
            [],
        )
        .unwrap();
    });
    setup.until("tasks", |rows| {
        rows.iter().any(|row| row[0] == "2" && row[4] != "ready")
    });

    let (state, reason) = state_of(&setup, "2");

    assert_eq!(state, "held");
    assert!(
        reason.contains("until owner/repo#7 merges")
            || reason.contains("until github:owner/repo#7 merges"),
        "{reason}"
    );
}

const FIX: &str = r#"
start = "triage"

[[steps]]
id = "triage"
decides = "human"
effect = "none"
options = ["approved", "rejected"]
next = { approved = "done", rejected = "stop" }
"#;

/// The `support-day` schedule, whose fix tasks wait on a person, so the fake `claude` only
/// serves the scan's own calls.
fn scan(name: &str) -> Setup {
    let setup = support_day(name);
    let files = [
        (
            "factory/factory.toml",
            "name = \"demo\"\n\n[request]\nworkflow = \"fix\"\nband = \"today\"\n",
        ),
        ("factory/workflows/fix.toml", FIX),
    ];
    for (path, content) in files {
        fs::write(setup.dir.join(path), content).unwrap();
    }
    setup
}

fn finding(key: &str) -> serde_json::Value {
    json!({ "name": "finding", "arguments": {
        "key": key,
        "title": "The disk is full",
        "details": "df shows 100% on /var",
    } })
}

#[test]
fn a_finding_opens_one_fix_task_that_relates_to_the_scan() {
    let mut setup = scan("finding-opens");
    setup.calls(&[json!([finding("disk-full"), ask()])]);
    setup.publish(&tick("2026-11-19T08:00:00Z"));
    setup.start();

    let tasks = setup.until("tasks", |rows| rows.len() == 2);

    let fix = tasks.iter().find(|row| row[1] == "finding:1:1:disk-full");
    assert!(
        fix.is_some_and(|row| row[2] == "fix" && row[5] == "today"),
        "{tasks:?}"
    );
}

/// The scan's task row, whose prompts the typed log keeps: those that start with the schedule's own.
fn wakes(setup: &Setup) -> Vec<String> {
    setup
        .typed()
        .into_iter()
        .filter(|typed| typed.starts_with("Sweep the support queue."))
        .collect()
}

#[test]
fn the_same_finding_next_run_opens_no_task_and_the_next_prompt_remembers_it() {
    let mut setup = scan("finding-repeats");
    setup.calls(&[json!([finding("disk-full"), ask()]), finding("disk-full")]);
    setup.publish(&tick("2026-11-19T08:00:00Z"));
    setup.start();
    setup.until("tasks", |rows| rows.len() == 2);
    setup.until("tasks", |rows| {
        rows.iter()
            .any(|row| row[1].starts_with("schedule") && row[4] == "asleep")
    });

    setup.publish(&tick("2026-11-19T09:00:00Z"));

    setup.until("outbox", |_| wakes(&setup).len() == 1);
    let woken = &wakes(&setup)[0];
    assert!(
        woken.contains("disk-full: The disk is full (reported in the last 1 runs in a row; fix task finding:1:1:disk-full)"),
        "{woken}"
    );
    setup.calls_left(0);
    setup.until("runs", |_| setup.replies().len() == 3);
    assert_eq!(setup.rows("tasks").len(), 2);
    let replies: Vec<_> = setup.replies().iter().map(reply).collect();
    assert!(replies.iter().all(|(_, error)| !error), "{replies:?}");
    assert!(replies[2].0.contains("already open"), "{replies:?}");
}

#[test]
fn a_finding_reported_three_runs_in_a_row_moves_its_fix_task_up_a_band() {
    let mut setup = scan("finding-streak");
    setup.calls(&[
        json!([finding("disk-full"), ask()]),
        finding("disk-full"),
        finding("disk-full"),
    ]);
    setup.publish(&tick("2026-11-19T08:00:00Z"));
    setup.start();
    setup.until("tasks", |rows| rows.len() == 2);
    for (n, hour) in ["09", "10"].into_iter().enumerate() {
        setup.until("runs", |rows| rows.len() == n + 1 && rows[n][7] == "asleep");
        setup.publish(&tick(&format!("2026-11-19T{hour}:00:00Z")));
    }

    let tasks = setup.until("tasks", |rows| {
        rows.iter()
            .any(|row| row[1] == "finding:1:1:disk-full" && row[5] == "now")
    });

    assert_eq!(tasks.len(), 2, "{tasks:?}");
}

/// A thread comment from ana on pull request 7 at `url`.
fn thread_comment_at(id: u64) -> Message {
    let mut comment = thread_comment();
    comment.data["github_id"] = json!(id);
    comment.data["url"] = json!(format!(
        "https://github.com/owner/repo/pull/7#discussion_r{id}"
    ));
    comment
}

/// A review of pull request 7 that asks for changes.
fn changes_requested() -> Message {
    on_pull(
        "github.pull_request_review.submitted",
        json!({
            "state": "changes_requested", "actor": "ana", "body": "Two things.", "github_id": 301,
            "url": "https://github.com/owner/repo/pull/7#pullrequestreview-301"
        }),
    )
}

/// Task 1 sleeps three seconds. A thread comment on its pull request wakes it, then a second one
/// and a review reach it. Returns once all three are typed.
fn woken_by_feedback(name: &str) -> Setup {
    let mut setup = Setup::new(name);
    setup.calls(&[wait(json!({ "type": "time", "until": "3 seconds" }))]);
    setup.publish(&requested(42));
    setup.start();
    setup.until("runs", |rows| rows.len() == 1 && rows[0][7] == "asleep");
    setup.publish(&thread_comment_at(802));
    setup.until("outbox", |rows| with(rows, 3, "confirmed") >= 2);
    setup.publish(&thread_comment_at(803));
    setup.publish(&changes_requested());
    setup.until("outbox", |rows| with(rows, 3, "confirmed") >= 4);
    setup
}

const REVIEW_URL: &str = "https://github.com/owner/repo/pull/7#pullrequestreview-301";
const THREAD_URL: &str = "https://github.com/owner/repo/pull/7#discussion_r802";
const OTHER_URL: &str = "https://github.com/owner/repo/pull/7#discussion_r803";

/// Calls `result` on task 1's live run with `feedback`, and returns the reply's text and error flag.
fn result_sorting(setup: &Setup, feedback: serde_json::Value) -> (String, bool) {
    let session = setup.rows("runs").last().unwrap()[4].clone();
    let mut call = passed_at("abc0000000000000000000000000000000000000");
    call["arguments"]["feedback"] = feedback;
    let call = json!({ "jsonrpc": "2.0", "id": 1, "method": "tools/call", "params": call });
    reply(&setup.mcp(&session, &[call])[0])
}

/// Raises an agent ask on task 1's live run whose question names `urls`.
fn ask_about(setup: &Setup, urls: &[&str]) {
    let session = setup.rows("runs").last().unwrap()[4].clone();
    let mut call = ask();
    call["arguments"]["question"] = json!(format!("Your call on {}?", urls.join(" and ")));
    let call = json!({ "jsonrpc": "2.0", "id": 1, "method": "tools/call", "params": call });
    let (text, error) = reply(&setup.mcp(&session, &[call])[0]);
    assert!(!error, "{text}");
}

/// Answers task 1's first ask and waits for the answer to reach the run.
fn answer_the_ask(setup: &Setup) {
    let answered = setup.priory(&["answer", "1", "sqlite", "--revision", "1"]);
    assert!(answered.status.success(), "{answered:?}");
    setup.until("outbox", |rows| {
        rows.iter()
            .any(|row| row[4].starts_with("Answer to ask 1") && row[3] == "confirmed")
    });
}

#[test]
fn a_comment_that_wakes_the_task_comes_with_the_rule_for_sorting_it() {
    let setup = woken_by_feedback("triage-wake");

    let typed = setup.typed();
    assert!(
        typed[1].contains("sort each item by its URL as one of: trivial"),
        "{typed:?}"
    );
}

#[test]
fn a_result_sorting_every_item_stores_the_triage_and_task_json_shows_it() {
    let setup = woken_by_feedback("triage-stored");
    let sorted =
        json!({ REVIEW_URL: "persons-call", THREAD_URL: "trivial", OTHER_URL: "nothing-to-do" });
    ask_about(&setup, &[REVIEW_URL]);
    answer_the_ask(&setup);

    let (text, error) = result_sorting(&setup, sorted);

    assert!(!error, "{text}");
    let triage = task_json(&setup, "1")["triage"].clone();
    let mut classes: Vec<_> = triage
        .as_array()
        .unwrap()
        .iter()
        .map(|item| {
            (
                item["item"].as_str().unwrap(),
                item["class"].as_str().unwrap(),
            )
        })
        .collect();
    classes.sort();
    assert_eq!(
        classes,
        [
            (THREAD_URL, "trivial"),
            (OTHER_URL, "nothing-to-do"),
            (REVIEW_URL, "persons-call")
        ]
    );
}

#[test]
fn a_result_leaving_items_unsorted_is_refused_once_with_every_item_named() {
    let setup = woken_by_feedback("triage-refused");
    let partial = json!({ REVIEW_URL: "persons-call" });

    let (text, error) = result_sorting(&setup, partial);

    assert!(error, "{text}");
    assert!(
        text.starts_with(&format!(
            "feedback items {THREAD_URL}, {OTHER_URL} have no class"
        )),
        "{text}"
    );
    assert_eq!(task_json(&setup, "1")["triage"], json!([]));
}

#[test]
fn a_result_need_not_sort_an_item_typed_before_the_tasks_last_result() {
    let setup = woken_by_feedback("triage-since-result");
    // An earlier run's result, as an upgrade leaves one, came after the first comment was typed.
    let db = rusqlite::Connection::open(setup.dir.join("priory.db")).unwrap();
    db.execute_batch(&format!(
        "INSERT INTO runs (id, task, step, tmux, session, ended, ended_as)
           VALUES (0, 1, 'implement', 'priory-1', 'old', '2026-11-19T08:00:00Z', 'moved');
         INSERT INTO results (run, task, step, outcome, summary) VALUES (0, 1, 'implement', 'passed', 'old');
         UPDATE outbox SET run = 0 WHERE instr(text, '{THREAD_URL}') > 0;"
    ))
    .unwrap();
    ask_about(&setup, &[REVIEW_URL]);
    answer_the_ask(&setup);

    let (text, error) = result_sorting(
        &setup,
        json!({ REVIEW_URL: "persons-call", OTHER_URL: "trivial" }),
    );

    assert!(!error, "{text}");
}

const APPROVE: &str = r#"
start = "approve"

[[steps]]
id = "approve"
decides = "human"
effect = "none"
options = ["approved", "rejected"]
next = { approved = "done", rejected = "stop" }
"#;

const T0: &str = "2026-11-21T10:00:00Z";
const AN_HOUR_LATER: &str = "2026-11-21T11:00:00Z";

/// Runner `host` of a factory that has runners `a` and `b`, on the log of `bus` when given.
fn runner(test: &str, host: &str, bus: Option<&Setup>) -> Setup {
    let mut setup = Setup::new(&format!("{test}-{host}"));
    for (path, content) in [
        ("factory/runners/a.toml", "platform = { os = \"linux\" }\n"),
        ("factory/runners/b.toml", "platform = { os = \"linux\" }\n"),
        ("factory/workflows/approve.toml", APPROVE),
        ("proc/sys/kernel/hostname", &format!("{host}\n")),
    ] {
        let file = setup.dir.join(path);
        fs::create_dir_all(file.parent().unwrap()).unwrap();
        fs::write(file, content).unwrap();
    }
    if let Some(other) = bus {
        setup.bus = other.bus.clone();
    }
    setup
}

/// Waits until the log holds a message of `kind` whose data has every field of `fields`.
fn logged(setup: &Setup, kind: &str, fields: serde_json::Value) {
    let deadline = Instant::now() + Duration::from_secs(60);
    loop {
        let messages = setup
            .bus()
            .messages(&herdr_bus::MessageQuery {
                output: Some(OUTPUT.into()),
                limit: 1000,
                ..herdr_bus::MessageQuery::default()
            })
            .unwrap();
        let found = messages.iter().any(|stored| {
            stored.message.kind == kind
                && fields
                    .as_object()
                    .unwrap()
                    .iter()
                    .all(|(field, value)| &stored.message.data[field] == value)
        });
        if found {
            return;
        }
        assert!(
            Instant::now() < deadline,
            "no {kind} {fields} in the log\ndaemon: {}",
            fs::read_to_string(setup.dir.join("daemon.log")).unwrap_or_default()
        );
        std::thread::sleep(Duration::from_millis(50));
    }
}

#[test]
fn a_runner_away_for_an_hour_keeps_its_asked_task_and_its_answer_and_loses_only_a_task_it_never_started()
 {
    let mut a = runner("away", "a", None);
    let mut b = runner("away", "b", Some(&a));
    let mut asked = requested(1);
    asked.data["workflow"] = json!("approve");
    a.publish(&asked);
    a.publish(&requested(2));
    // No room on `a`, so task 2 never starts there.
    a.memory(0);
    let exe = Path::new(env!("CARGO_BIN_EXE_priory"));

    a.start_with(exe, &[("PRIORY_NOW", T0)]);
    let asks = a.until("asks", |rows| rows.len() == 1);
    logged(
        &a,
        "priory.task.held",
        json!({ "key": "github:owner/repo#1", "runner": "a", "hold": "kept" }),
    );
    logged(
        &a,
        "priory.task.held",
        json!({ "key": "github:owner/repo#2", "runner": "a", "hold": "waiting" }),
    );
    a.crash();

    b.start_with(exe, &[("PRIORY_NOW", AN_HOUR_LATER)]);
    let ask = format!("a:{}", asks[0][0]);
    let factory = b.dir.join("factory");
    for answer in ["approved", "rejected"] {
        let dir = factory.to_str().unwrap();
        let sent = b.priory(&["answer", dir, &ask, answer, "--revision", "1"]);
        assert!(
            sent.status.success(),
            "{}",
            String::from_utf8_lossy(&sent.stderr)
        );
    }
    b.publish(&requested(3));
    let tasks =
        b.until_own_tasks(|rows| rows.iter().filter(|row| row[4] == "running").count() == 2);
    let mut keys: Vec<&str> = tasks.iter().map(|row| row[1].as_str()).collect();
    keys.sort_unstable();
    assert_eq!(
        keys,
        ["github:owner/repo#2", "github:owner/repo#3"],
        "{tasks:?}"
    );

    a.memory(60);
    a.start_with(exe, &[("PRIORY_NOW", AN_HOUR_LATER)]);
    let tasks = a.until_own_tasks(|rows| {
        rows.iter()
            .all(|row| ["done", "dropped"].contains(&row[4].as_str()))
    });
    let states: Vec<[&str; 2]> = tasks
        .iter()
        .map(|row| [row[1].as_str(), row[4].as_str()])
        .collect();
    assert_eq!(
        states,
        [
            ["github:owner/repo#1", "done"],
            ["github:owner/repo#2", "dropped"]
        ],
        "the first answer stands, and the task that moved is not a's any more"
    );
    assert!(a.rows("runs").is_empty(), "a never ran task 2");
    let runs = b.rows("runs");
    assert_eq!(runs.len(), 2, "{runs:?}");
}

#[test]
fn a_takeover_waits_the_whole_lease_after_an_alive_message_sent_partway_through_a_second() {
    let mut a = runner("lease-second", "a", None);
    let mut b = runner("lease-second", "b", Some(&a));
    a.publish(&requested(1));
    a.memory(0);
    let exe = Path::new(env!("CARGO_BIN_EXE_priory"));
    a.start_with(exe, &[("PRIORY_NOW", "2026-11-21T10:00:00.900Z")]);
    logged(
        &a,
        "priory.task.held",
        json!({ "key": "github:owner/repo#1", "runner": "a", "hold": "waiting" }),
    );
    a.crash();

    // 29 minutes 59.6 seconds after a's last alive message: its lease still runs.
    b.start_with(exe, &[("PRIORY_NOW", "2026-11-21T10:30:00.500Z")]);
    b.until("inbox", |rows| {
        rows.iter()
            .any(|row| row[1] == "priory.runner.alive" && row[2] == "b")
    });
    b.crash();
    b.start_with(exe, &[("PRIORY_NOW", "2026-11-21T10:31:00Z")]);
    logged(
        &b,
        "priory.task.claimed",
        json!({ "key": "github:owner/repo#1", "runner": "b", "from": "a" }),
    );

    let takeovers: Vec<String> = b
        .bus()
        .messages(&herdr_bus::MessageQuery {
            output: Some(OUTPUT.into()),
            limit: 1000,
            ..herdr_bus::MessageQuery::default()
        })
        .unwrap()
        .into_iter()
        .filter(|stored| {
            stored.message.kind == "priory.task.claimed" && stored.message.data["from"] == "a"
        })
        .map(|stored| stored.message.time.to_string())
        .collect();
    assert_eq!(takeovers, ["2026-11-21T10:31:00Z"]);
}

#[test]
fn a_person_gives_a_started_task_to_another_runner_which_starts_it_over_and_its_old_runner_drops_it()
 {
    let mut a = runner("give", "a", None);
    let mut b = runner("give", "b", Some(&a));
    let mut asked = requested(1);
    asked.data["workflow"] = json!("approve");
    a.publish(&asked);
    let exe = Path::new(env!("CARGO_BIN_EXE_priory"));
    a.start_with(exe, &[("PRIORY_NOW", T0)]);
    a.until("asks", |rows| rows.len() == 1);
    logged(
        &a,
        "priory.task.held",
        json!({ "key": "github:owner/repo#1", "runner": "a", "hold": "kept" }),
    );
    a.crash();

    b.start_with(exe, &[("PRIORY_NOW", AN_HOUR_LATER)]);
    b.until("inbox", |rows| {
        rows.iter().any(|row| {
            row.contains(&"priory.runner.alive".to_owned()) && row.contains(&"b".to_owned())
        })
    });
    let factory = b.dir.join("factory");
    let give = |runner: &str, flags: &[&str]| {
        let dir = factory.to_str().unwrap();
        b.command(exe.to_str().unwrap())
            .env("PRIORY_NOW", AN_HOUR_LATER)
            .args(["give", dir, "github:owner/repo#1", runner])
            .args(flags)
            .output()
            .unwrap()
    };
    let given = give("b", &[]);
    assert_eq!(
        String::from_utf8_lossy(&given.stdout),
        "github:owner/repo#1 given to runner b: b takes it and a drops it as each reads the log\n",
        "{}",
        String::from_utf8_lossy(&given.stderr)
    );
    // b lists a's ask too, as `a:<ask>`, so it waits for an ask of its own.
    b.until("asks", |rows| rows.iter().any(|row| !row[0].contains(':')));

    a.start_with(exe, &[("PRIORY_NOW", AN_HOUR_LATER)]);
    let tasks = a.until_own_tasks(|rows| rows[0][4] == "dropped");
    assert_eq!(tasks.len(), 1);
    let refused = give("b", &[]);
    assert_eq!(
        String::from_utf8_lossy(&refused.stderr),
        "priory give: runner b holds github:owner/repo#1 already\n"
    );
    let unknown = give("c", &[]);
    assert_eq!(
        String::from_utf8_lossy(&unknown.stderr),
        "priory give: runner c has no runner file in runners/\n"
    );

    // b, alive at this hour, holds a live lease.
    let back = give("a", &["--force"]);
    assert!(
        back.status.success(),
        "{}",
        String::from_utf8_lossy(&back.stderr)
    );
    let tasks = a.until_own_tasks(|rows| rows.len() == 2 && rows[1][4] == "asleep");
    assert_eq!(tasks[0][4], "dropped", "{tasks:?}");
    b.until_own_tasks(|rows| rows[0][4] == "dropped");
}

#[test]
fn a_person_gives_a_task_whose_owner_may_still_run_it_only_with_force() {
    let mut a = runner("give-live", "a", None);
    let mut b = runner("give-live", "b", Some(&a));
    let mut asked = requested(1);
    asked.data["workflow"] = json!("approve");
    a.publish(&asked);
    let exe = Path::new(env!("CARGO_BIN_EXE_priory"));
    a.start_with(exe, &[("PRIORY_NOW", T0)]);
    a.until("asks", |rows| rows.len() == 1);
    logged(
        &a,
        "priory.task.held",
        json!({ "key": "github:owner/repo#1", "runner": "a", "hold": "kept" }),
    );

    b.start_with(exe, &[("PRIORY_NOW", "2026-11-21T10:10:00Z")]);
    b.until("inbox", |rows| {
        rows.iter().any(|row| {
            row.contains(&"priory.runner.alive".to_owned()) && row.contains(&"b".to_owned())
        })
    });
    let factory = b.dir.join("factory");
    let give = |now: &str, flags: &[&str]| {
        let dir = factory.to_str().unwrap();
        b.command(exe.to_str().unwrap())
            .env("PRIORY_NOW", now)
            .args(["give", dir, "github:owner/repo#1", "b"])
            .args(flags)
            .output()
            .unwrap()
    };
    let refused = give("2026-11-21T10:29:59Z", &[]);
    assert_eq!(
        String::from_utf8_lossy(&refused.stderr),
        "priory give: runner a's lease lasts until 2026-11-21T10:30:00Z, and a may still run \
         github:owner/repo#1: give it then, or pass --force\n"
    );
    std::thread::sleep(Duration::from_secs(2));
    assert!(b.own_tasks().is_empty(), "nothing moved");
    assert_eq!(a.own_tasks()[0][4], "asleep");

    let forced = give("2026-11-21T10:10:00Z", &["--force"]);
    assert!(
        forced.status.success(),
        "{}",
        String::from_utf8_lossy(&forced.stderr)
    );
    b.until("asks", |rows| rows.len() == 1);
    a.until_own_tasks(|rows| rows[0][4] == "dropped");
}

#[test]
fn a_runner_that_joins_late_reads_a_finished_task_without_running_it_again() {
    let mut a = runner("late", "a", None);
    let mut b = runner("late", "b", Some(&a));
    let mut asked = requested(1);
    asked.data["workflow"] = json!("approve");
    a.publish(&asked);
    let exe = Path::new(env!("CARGO_BIN_EXE_priory"));
    a.start_with(exe, &[("PRIORY_NOW", T0)]);
    let asks = a.until("asks", |rows| rows.len() == 1);
    let answered = a.priory(&["answer", &asks[0][0], "approved", "--revision", "1"]);
    assert!(
        answered.status.success(),
        "{}",
        String::from_utf8_lossy(&answered.stderr)
    );
    logged(
        &a,
        "priory.task.held",
        json!({ "key": "github:owner/repo#1", "runner": "a", "hold": "ended" }),
    );

    b.start_with(exe, &[("PRIORY_NOW", T0)]);
    logged(
        &b,
        "priory.task.claimed",
        json!({ "key": "github:owner/repo#1", "runner": "b" }),
    );
    b.until("inbox", |rows| {
        rows.iter().any(|row| row.contains(&"refused".to_owned()))
    });
    assert!(
        b.own_tasks().is_empty(),
        "b's late claim of the finished request loses"
    );
}

#[test]
fn a_runner_added_to_a_factory_that_had_one_does_not_run_its_finished_requests_again() {
    let mut a = runner("joined", "a", None);
    let mut b = runner("joined", "b", Some(&a));
    let runners = a.dir.join("factory/runners");
    let later = a.dir.join("runners-later");
    fs::rename(&runners, &later).unwrap();
    let exe = Path::new(env!("CARGO_BIN_EXE_priory"));
    a.calls(&[result("passed")]);
    a.publish(&requested(1));
    a.start_with(exe, &[("PRIORY_NOW", T0)]);
    a.until_own_tasks(|rows| rows.first().is_some_and(|row| row[4] == "done"));
    a.crash();

    fs::rename(&later, &runners).unwrap();
    a.start_with(exe, &[("PRIORY_NOW", T0)]);
    logged(&a, "priory.runner.alive", json!({ "runner": "a" }));
    b.start_with(exe, &[("PRIORY_NOW", T0)]);
    b.until("inbox", |rows| {
        rows.iter().any(|row| {
            row.contains(&"priory.runner.alive".to_owned()) && row.contains(&"b".to_owned())
        })
    });

    assert!(
        b.own_tasks().is_empty(),
        "b does not run the request a finished before it had runners"
    );
}

