#[test]
fn a_copy_reopened_on_a_runner_whose_key_another_runner_owns_drops_with_the_owner_named() {
    let mut a = runner("reopen-elsewhere", "a", None);
    let mut b = runner("reopen-elsewhere", "b", Some(&a));
    let exe = Path::new(env!("CARGO_BIN_EXE_priory"));
    a.calls(&[result("passed")]);
    a.publish(&requested(1));
    a.start_with(exe, &[("PRIORY_NOW", T0)]);
    a.until_own_tasks(|rows| rows.first().is_some_and(|row| row[4] == "done"));
    logged(
        &a,
        "priory.task.held",
        json!({ "key": "github:owner/repo#1", "runner": "a", "hold": "ended" }),
    );
    a.crash();

    // A new request for the key goes to b, which a hears only once it is back.
    b.publish(&requested(1));
    b.start_with(exe, &[("PRIORY_NOW", T0)]);
    b.until_own_tasks(|rows| rows.len() == 1);
    a.start_with(exe, &[("PRIORY_NOW", T0)]);
    a.until("inbox", |rows| {
        rows.iter()
            .any(|row| row[1] == "priory.task.claimed" && row[4] == "refused")
    });
    // The comment comes after the task was done, to the second.
    std::thread::sleep(Duration::from_millis(1100));

    a.publish(
        &Message::new(
            "github.issues.comment",
            json!({ "repo": "owner/repo", "issue": 1, "actor": "ana", "body": "Still broken.",
                "url": "u", "github_id": 901 }),
        )
        .subject("owner/repo#1")
        .time(herdr_bus::Timestamp::now()),
    );

    let tasks = a.until_own_tasks(|rows| rows[0][4] == "dropped");
    assert_eq!(tasks.len(), 1, "{tasks:?}");
    let task = a.priory(&["task", &tasks[0][0], "--json"]);
    let task: serde_json::Value = serde_json::from_slice(&task.stdout).unwrap();
    assert_eq!(task["reason"], "owned by runner b", "{task}");
    // b starts its task on its own clock, so wait for it rather than read it once.
    b.until_own_tasks(|rows| rows[0][4] == "running");
}

/// A Linear request for `issue` keyed by its identifier.
fn linear_requested(issue: &str, source: &str) -> Message {
    let key = format!("linear:{issue}");
    let mut request = requested(1);
    request.data["key"] = json!(key);
    request.data["source"] = json!(source);
    request.subject(key)
}

/// `from` moved to another Linear team, where it is `to`.
fn team_moved(from: &str, to: &str) -> Message {
    let mut moved = Message::new(
        "linear.issue.updated",
        json!({ "issue": to, "linear_id": "history-1", "team": "OPS", "state": "Todo",
                "changed": ["identifier"], "previous_issue": from }),
    )
    .subject(to);
    moved.data["description"] = json!(null);
    moved
}

#[test]
fn a_task_moved_twice_to_other_linear_teams_keeps_its_claim_starts_and_is_not_claimed_again() {
    let mut a = runner("team-moves", "a", None);
    let mut b = runner("team-moves", "b", Some(&a));
    a.publish(&linear_requested("ENG-7", "first"));
    a.memory(0);
    let exe = Path::new(env!("CARGO_BIN_EXE_priory"));
    a.start_with(exe, &[("PRIORY_NOW", T0)]);
    logged(
        &a,
        "priory.task.held",
        json!({ "key": "linear:ENG-7", "runner": "a", "hold": "waiting" }),
    );
    b.start_with(exe, &[("PRIORY_NOW", T0)]);
    // b read the request before a's claim, so it claimed too, and lost.
    for side in [&a, &b] {
        side.until("inbox", |rows| {
            rows.iter().any(|row| {
                row[1] == "priory.task.claimed" && row[2] == "linear:ENG-7" && row[4] == "refused"
            })
        });
    }

    a.publish(&team_moved("ENG-7", "OPS-3"));
    a.publish(&team_moved("OPS-3", "SUP-9"));
    a.publish(&linear_requested("SUP-9", "later"));
    b.until("inbox", |rows| {
        rows.iter()
            .any(|row| row[1] == "factory.task.requested" && row[2] == "linear:SUP-9")
    });
    a.memory(60);

    let tasks = a.until_own_tasks(|rows| rows.first().is_some_and(|row| row[4] == "running"));
    assert_eq!(tasks[0][1], "linear:SUP-9", "{tasks:?}");
    for side in [&a, &b] {
        let db = rusqlite::Connection::open(side.dir.join("priory.db")).unwrap();
        let claims: Vec<(String, String)> = db
            .prepare("SELECT key, runner FROM claims ORDER BY key")
            .unwrap()
            .query_map([], |row| Ok((row.get(0)?, row.get(1)?)))
            .unwrap()
            .collect::<Result<_, _>>()
            .unwrap();
        assert_eq!(claims, [("linear:SUP-9".to_owned(), "a".to_owned())]);
    }
    assert!(b.own_tasks().is_empty(), "{:?}", b.own_tasks());
}

#[test]
fn a_lead_task_runs_on_the_runner_of_the_ask_it_answers_without_a_claim_and_cannot_be_given() {
    let mut a = hands_off("lead-runner", WORKFLOW);
    for (path, content) in [
        ("factory/runners/a.toml", "platform = { os = \"linux\" }\n"),
        ("factory/runners/b.toml", "platform = { os = \"linux\" }\n"),
        ("proc/sys/kernel/hostname", "a\n"),
    ] {
        let file = a.dir.join(path);
        fs::create_dir_all(file.parent().unwrap()).unwrap();
        fs::write(file, content).unwrap();
    }
    let exe = Path::new(env!("CARGO_BIN_EXE_priory"));
    a.calls(&[ask()]);
    a.publish(&requested(42));
    a.start_with(exe, &[("PRIORY_NOW", T0)]);

    let lead = "priory:ask:1:1";
    a.until_own_tasks(|rows| rows.iter().any(|row| row[1] == lead && row[4] == "running"));
    let claims: Vec<serde_json::Value> = a
        .bus()
        .messages(&herdr_bus::MessageQuery {
            output: Some(OUTPUT.into()),
            limit: 1000,
            ..herdr_bus::MessageQuery::default()
        })
        .unwrap()
        .into_iter()
        .filter(|stored| stored.message.kind == "priory.task.claimed")
        .map(|stored| stored.message.data["key"].clone())
        .collect();
    assert_eq!(
        claims,
        [json!("github:owner/repo#42")],
        "no other runner has the lead task's source, so its key stays off the log"
    );

    let factory = a.dir.join("factory");
    let given = a.priory(&["give", factory.to_str().unwrap(), lead, "b", "--force"]);
    assert_eq!(
        String::from_utf8_lossy(&given.stderr),
        "priory give: priory:ask:1:1 is a lead task, which stays on the runner of the ask it answers\n"
    );
    assert!(!given.status.success());
}

