/// Gives `setup`'s daemon a `[serve]` on loopback, so it serves the web API once it starts.
fn with_serve(setup: &Setup) {
    let file = setup.dir.join("factory/factory.toml");
    let mut toml = fs::read_to_string(&file).unwrap();
    toml.push_str("\n[serve]\nlisten = \"127.0.0.1:0\"\ntoken_env = \"PRIORY_TEST_TOKEN\"\n");
    fs::write(file, toml).unwrap();
}

/// Starts `setup`'s daemon at `now` with its token and returns the address its server listens on.
fn start_serving(setup: &mut Setup, now: &str) -> String {
    let exe = Path::new(env!("CARGO_BIN_EXE_priory"));
    setup.start_with(
        exe,
        &[("PRIORY_NOW", now), ("PRIORY_TEST_TOKEN", SERVE_TOKEN)],
    );
    let deadline = Instant::now() + Duration::from_secs(60);
    loop {
        let log = fs::read_to_string(setup.dir.join("daemon.log")).unwrap_or_default();
        if let Some(address) = log
            .lines()
            .find_map(|line| line.trim().strip_prefix("priory: serving on http://"))
        {
            return address.to_owned();
        }
        assert!(Instant::now() < deadline, "the daemon never served: {log}");
        std::thread::sleep(Duration::from_millis(50));
    }
}

/// Sends one request with the token and returns its status and JSON body.
fn runner_http(address: &str, method: &str, path: &str, body: &str) -> (u16, serde_json::Value) {
    use std::io::{Read, Write};
    let mut stream = std::net::TcpStream::connect(address).unwrap();
    stream
        .set_read_timeout(Some(Duration::from_secs(60)))
        .unwrap();
    let head = format!(
        "{method} {path} HTTP/1.1\r\nHost: {address}\r\nAuthorization: Bearer {SERVE_TOKEN}\r\n\
         Content-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
        body.len()
    );
    stream.write_all(head.as_bytes()).unwrap();
    let mut response = String::new();
    stream.read_to_string(&mut response).unwrap();
    let status = response[9..12].parse().unwrap();
    let body = response.split_once("\r\n\r\n").map_or("", |(_, body)| body);
    (status, serde_json::from_str(body).unwrap_or(json!(body)))
}

/// Waits until `/api/asks?all=1` on `address` lists ask `id` and `done` holds for it.
fn until_ask(
    address: &str,
    id: &str,
    done: impl Fn(&serde_json::Value) -> bool,
) -> serde_json::Value {
    let deadline = Instant::now() + Duration::from_secs(60);
    loop {
        let (status, asks) = runner_http(address, "GET", "/api/asks?all=1", "");
        assert_eq!(status, 200, "{asks}");
        let found = asks["asks"]
            .as_array()
            .unwrap()
            .iter()
            .find(|ask| ask["id"] == id)
            .cloned();
        if let Some(ask) = found.filter(&done) {
            return ask;
        }
        assert!(Instant::now() < deadline, "no ask {id} as wanted in {asks}");
        std::thread::sleep(Duration::from_millis(100));
    }
}

/// The messages of `kind` on the log, oldest first.
fn on_log(setup: &Setup, kind: &str) -> Vec<Message> {
    let mut messages: Vec<Message> = setup
        .bus()
        .messages(&herdr_bus::MessageQuery {
            output: Some(OUTPUT.into()),
            limit: 1000,
            ..herdr_bus::MessageQuery::default()
        })
        .unwrap()
        .into_iter()
        .filter(|stored| stored.message.kind == kind)
        .map(|stored| stored.message)
        .collect();
    messages.reverse();
    messages
}

/// Runners `a` and `b` on one log, `a` asleep on an approve ask and `b` serving: returns both, the
/// ask's id on `a` and `b`'s address.
fn asked_on_a(test: &str) -> (Setup, Setup, String, String) {
    let mut a = runner(test, "a", None);
    let mut b = runner(test, "b", Some(&a));
    with_serve(&b);
    let mut asked = requested(1);
    asked.data["workflow"] = json!("approve");
    a.publish(&asked);
    a.start_with(
        Path::new(env!("CARGO_BIN_EXE_priory")),
        &[("PRIORY_NOW", T0)],
    );
    let asks = a.until("asks", |rows| rows.len() == 1);
    let address = start_serving(&mut b, T0);
    (a, b, asks[0][0].clone(), address)
}

#[test]
fn another_runners_open_ask_is_listed_with_its_runner_on_the_asks_and_desk_endpoints() {
    let (_a, b, ask, address) = asked_on_a("remote-listed");
    let id = format!("a:{ask}");

    let listed = until_ask(&address, &id, |ask| ask["state"] == "open");

    assert_eq!(listed["runner"], "a", "{listed}");
    assert_eq!(listed["revision"], 1, "{listed}");
    assert!(listed["last_seen"].is_string(), "{listed}");
    let (_, desk) = runner_http(&address, "GET", "/api/desk", "");
    let item = desk["items"]
        .as_array()
        .unwrap()
        .iter()
        .find(|item| item["id"] == id)
        .unwrap_or_else(|| panic!("{desk}"));
    assert_eq!(item["runner"], "a");
    assert!(
        desk["ranked"]
            .as_array()
            .unwrap()
            .iter()
            .any(|item| item["id"] == id),
        "{desk}"
    );
    let cli = b.priory(&["asks", "--json"]);
    let cli: serde_json::Value = serde_json::from_slice(&cli.stdout).unwrap();
    assert!(
        cli["asks"]
            .as_array()
            .unwrap()
            .iter()
            .any(|ask| ask["id"] == id),
        "{cli}"
    );
}

#[test]
fn an_answer_sent_to_another_runners_ask_is_accepted_applied_by_its_runner_and_its_outcome_listed()
{
    let (a, _b, ask, address) = asked_on_a("remote-answer");
    let id = format!("a:{ask}");
    until_ask(&address, &id, |ask| ask["state"] == "open");

    let (status, sent) = runner_http(
        &address,
        "POST",
        &format!("/api/asks/{id}/answer"),
        r#"{"option": "approved", "revision": 1}"#,
    );

    assert_eq!(status, 202, "{sent}");
    assert_eq!(sent["sent"], "a");
    let submission = sent["submission"].as_str().unwrap().to_owned();
    let closed = until_ask(&address, &id, |ask| {
        ask["state"] == "answered" && ask["submissions"][0]["outcome"] == "answered"
    });
    assert_eq!(closed["answer"], "approved", "{closed}");
    assert_eq!(closed["submissions"][0]["submission"], submission.as_str());
    a.until("tasks", |rows| rows[0][4] == "done");
}

#[test]
fn a_stale_answer_to_another_runners_ask_gets_409_and_nothing_is_published() {
    let (a, _b, ask, address) = asked_on_a("remote-stale");
    let id = format!("a:{ask}");
    until_ask(&address, &id, |ask| ask["state"] == "open");

    let (status, refused) = runner_http(
        &address,
        "POST",
        &format!("/api/asks/{id}/answer"),
        r#"{"option": "approved", "revision": 2}"#,
    );

    assert_eq!(status, 409, "{refused}");
    assert_eq!(refused["ask"]["id"], id.as_str(), "{refused}");
    assert_eq!(
        refused["error"],
        format!("ask {id} is at revision 1, not 2"),
        "{refused}"
    );
    assert!(on_log(&a, "priory.ask.answered").is_empty());
}

#[test]
fn a_remote_write_whose_publish_fails_says_the_log_may_hold_it_not_that_nothing_was_sent() {
    let (_a, b, ask, address) = asked_on_a("remote-unconfirmed");
    let id = format!("a:{ask}");
    until_ask(&address, &id, |ask| ask["state"] == "open");
    until_task(&address, ASKED_KEY, "a", |task| {
        task.is_some_and(|task| task["generation"] == 1)
    });
    let bus = rusqlite::Connection::open(&b.bus).unwrap();
    bus.execute_batch(
        "CREATE TRIGGER lost BEFORE INSERT ON messages BEGIN SELECT RAISE(ABORT, 'disk gone'); END",
    )
    .unwrap();

    let answered = runner_http(
        &address,
        "POST",
        &format!("/api/asks/{id}/answer"),
        r#"{"option": "approved", "revision": 1}"#,
    );
    let cancelled = runner_http(
        &address,
        "POST",
        &remote_act("a", ASKED_KEY, "cancel"),
        r#"{"generation": 1}"#,
    );
    bus.execute_batch("DROP TRIGGER lost").unwrap();

    for ((status, body), what) in [(answered, "ask"), (cancelled, "task")] {
        assert_eq!(status, 504, "{body}");
        let error = body["error"].as_str().unwrap_or_default();
        assert!(
            error.ends_with(&format!(
                ". The log may hold it: read the {what} before you retry"
            )),
            "{error}"
        );
    }
}

#[test]
fn of_two_answers_to_one_revision_the_first_stands_and_the_other_shows_refused_without_a_new_revision()
 {
    let (a, _b, ask, address) = asked_on_a("remote-twice");
    let id = format!("a:{ask}");
    until_ask(&address, &id, |ask| ask["state"] == "open");
    let path = format!("/api/asks/{id}/answer");

    let mut submissions = Vec::new();
    for option in ["approved", "rejected"] {
        let body = json!({ "option": option, "revision": 1 }).to_string();
        let (status, sent) = runner_http(&address, "POST", &path, &body);
        assert_eq!(status, 202, "{sent}");
        submissions.push(sent["submission"].as_str().unwrap().to_owned());
    }

    let closed = until_ask(&address, &id, |ask| {
        ask["submissions"]
            .as_array()
            .is_some_and(|sent| sent.iter().all(|sent| !sent["outcome"].is_null()))
            && ask["refused"]
                .as_array()
                .is_some_and(|refused| !refused.is_empty())
    });
    let outcomes: Vec<(&str, &str)> = closed["submissions"]
        .as_array()
        .unwrap()
        .iter()
        .map(|sent| {
            (
                sent["text"].as_str().unwrap(),
                sent["outcome"].as_str().unwrap(),
            )
        })
        .collect();
    assert!(outcomes.contains(&("approved", "answered")), "{closed}");
    assert!(outcomes.contains(&("rejected", "refused")), "{closed}");
    assert_eq!(closed["answer"], "approved", "{closed}");
    assert_eq!(
        closed["revision"], 1,
        "a refusal does not revise the question"
    );
    let versions: Vec<i64> = on_log(&a, "priory.ask.posted")
        .iter()
        .map(|post| post.data["version"].as_i64().unwrap())
        .collect();
    // Asked, answered, then refused: one post can cover changes read in one pass.
    assert_eq!(versions.last(), Some(&3), "{versions:?}");
    assert!(versions.is_sorted(), "{versions:?}");
}

#[test]
fn an_answer_sent_while_its_runner_is_away_is_applied_once_when_it_starts_again() {
    let (mut a, _b, ask, address) = asked_on_a("remote-away");
    let id = format!("a:{ask}");
    until_ask(&address, &id, |ask| ask["state"] == "open");
    a.crash();

    let (status, sent) = runner_http(
        &address,
        "POST",
        &format!("/api/asks/{id}/answer"),
        r#"{"option": "approved", "revision": 1}"#,
    );
    assert_eq!(status, 202, "{sent}");
    let pending = until_ask(&address, &id, |ask| {
        ask["submissions"]
            .as_array()
            .is_some_and(|sent| !sent.is_empty())
    });
    assert!(pending["submissions"][0]["outcome"].is_null(), "{pending}");
    assert_eq!(pending["state"], "open", "{pending}");

    a.start_with(
        Path::new(env!("CARGO_BIN_EXE_priory")),
        &[("PRIORY_NOW", T0)],
    );

    until_ask(&address, &id, |ask| {
        ask["state"] == "answered" && ask["submissions"][0]["outcome"] == "answered"
    });
    assert_eq!(on_log(&a, "priory.ask.applied").len(), 1);
}

#[test]
fn a_refused_dismiss_of_another_runners_ask_comes_back_with_the_owners_reason() {
    let (a, b, ask, address) = asked_on_a("remote-dismiss");
    let id = format!("a:{ask}");
    until_ask(&address, &id, |ask| ask["state"] == "open");
    let factory = b.dir.join("factory");

    let sent = b.priory(&["dismiss", "--revision", "1", factory.to_str().unwrap(), &id]);

    assert!(
        sent.status.success(),
        "{}",
        String::from_utf8_lossy(&sent.stderr)
    );
    let refused = until_ask(&address, &id, |ask| {
        ask["submissions"][0]["outcome"] == "refused"
    });
    assert_eq!(refused["submissions"][0]["verb"], "dismiss");
    assert_eq!(
        refused["submissions"][0]["why"],
        format!("ask {ask} moves its task on by its options: answer it instead"),
        "{refused}"
    );
    assert_eq!(a.rows("asks").len(), 1, "the ask stays open on a");
}

